/* @lc app=leetcode id=1695 lang=kotlin */ class Solution { fun maximumUniqueSubarray(nums: IntArray): Int = IntArray(10001).let { counts -> IntArray(3).let { st -> nums.forEach { x -> x.also { counts[x] = counts[x] + 1 }.also { st[1] = st[1] + x }.also { while (counts[x] > 1) st[1] -= nums[st[0]].also { counts[it] = counts[it] - 1 }.also { st[0] = st[0] + 1 } }.also { st[2] = maxOf(st[2], st[1]) } }.let { st[2] } } } }